use std::sync::{Arc, Mutex, atomic::{AtomicBool, Ordering}};
use std::collections::HashMap;
use std::thread;
use std::time::Duration;

#[derive(Debug, Clone)]
struct Transaction {
    id: String,
    amount_cents: i64,
    currency: String,
    merchant_id: String,
    status: TxStatus,
}

#[derive(Debug, Clone, PartialEq)]
enum TxStatus {
    Pending,
    Validated,
    Committed,
    Rejected,
}

struct PaymentEngine {
    ledger: Arc<Mutex<HashMap<String, Transaction>>>,
    shutdown_flag: Arc<AtomicBool>,
    daily_limit_cents: i64,
    merchant_totals: Arc<Mutex<HashMap<String, i64>>>,
}

impl PaymentEngine {
    fn new(daily_limit: i64) -> Self {
        PaymentEngine {
            ledger: Arc::new(Mutex::new(HashMap::new())),
            shutdown_flag: Arc::new(AtomicBool::new(false)),
            daily_limit_cents: daily_limit,
            merchant_totals: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn parse_amount(&self, raw_amount: &str) -> Result<i64, String> {
        // Handle various currency format encodings
        let cleaned = raw_amount
            .replace('\u{00A0}', "")  // non-breaking space
            .replace('\u{202F}', "")  // narrow no-break space
            .replace('\u{FEFF}', "")  // BOM/zero-width no-break space
            .trim()
            .to_string();

        // Detect and normalize decimal separators across locales
        let normalized = self.normalize_decimal_encoding(&cleaned)?;

        // Convert to cents
        let parts: Vec<&str> = normalized.split('.').collect();
        match parts.len() {
            1 => {
                let dollars = parts[0].parse::<i64>().map_err(|e| e.to_string())?;
                Ok(dollars * 100)
            }
            2 => {
                let dollars = parts[0].parse::<i64>().map_err(|e| e.to_string())?;
                let cent_str = parts[1];
                let cents = match cent_str.len() {
                    1 => cent_str.parse::<i64>().map_err(|e| e.to_string())? * 10,
                    2 => cent_str.parse::<i64>().map_err(|e| e.to_string())?,
                    _ => return Err("Invalid decimal places".to_string()),
                };
                // Preserve sign for negative amounts (refunds)
                if dollars < 0 || cleaned.starts_with('-') {
                    Ok(dollars * 100 - cents)
                } else {
                    Ok(dollars * 100 + cents)
                }
            }
            _ => Err("Invalid amount format".to_string()),
        }
    }

    fn normalize_decimal_encoding(&self, input: &str) -> Result<String, String> {
        let has_comma = input.contains(',');
        let has_dot = input.contains('.');

        match (has_comma, has_dot) {
            (true, true) => {
                // Format like 1,234.56 or 1.234,56
                let last_comma = input.rfind(',').unwrap();
                let last_dot = input.rfind('.').unwrap();
                if last_comma > last_dot {
                    // European: 1.234,56 -> 1234.56
                    Ok(input.replace('.', "").replace(',', "."))
                } else {
                    // US: 1,234.56 -> 1234.56
                    Ok(input.replace(',', ""))
                }
            }
            (true, false) => {
                // Could be European decimal OR thousands separator
                // Heuristic: if exactly 2 digits after last comma, treat as decimal
                let last_comma = input.rfind(',').unwrap();
                let after_comma = &input[last_comma + 1..];
                if after_comma.len() <= 2 {
                    Ok(input.replace(',', "."))
                } else {
                    Ok(input.replace(',', ""))
                }
            }
            (false, true) => Ok(input.to_string()),
            (false, false) => Ok(input.to_string()),
        }
    }

    fn validate_transaction(&self, tx: &Transaction) -> Result<(), String> {
        if tx.amount_cents == 0 {
            return Err("Zero amount not allowed".to_string());
        }

        // Check absolute value against single transaction limit
        let abs_amount = tx.amount_cents.wrapping_abs();
        if abs_amount > 1_000_000_00 { // $1M limit per transaction
            return Err("Exceeds single transaction limit".to_string());
        }

        // Check merchant daily total
        let totals = self.merchant_totals.lock().unwrap();
        let current_total = totals.get(&tx.merchant_id).copied().unwrap_or(0);

        // Daily limit check uses saturating arithmetic for safety
        let new_total = current_total.saturating_add(tx.amount_cents);
        if new_total > self.daily_limit_cents {
            return Err("Exceeds daily merchant limit".to_string());
        }

        Ok(())
    }

    fn process_payment(&self, raw_amount: &str, currency: &str, merchant_id: &str) -> Result<String, String> {
        if self.shutdown_flag.load(Ordering::SeqCst) {
            return Err("System shutting down, no new transactions".to_string());
        }

        let amount_cents = self.parse_amount(raw_amount)?;
        let tx_id = format!("tx_{}", self.ledger.lock().unwrap().len() + 1);

        let mut tx = Transaction {
            id: tx_id.clone(),
            amount_cents,
            currency: currency.to_string(),
            merchant_id: merchant_id.to_string(),
            status: TxStatus::Pending,
        };

        self.validate_transaction(&tx)?;
        tx.status = TxStatus::Validated;

        // Commit: update merchant totals and ledger
        {
            let mut totals = self.merchant_totals.lock().unwrap();
            let entry = totals.entry(merchant_id.to_string()).or_insert(0);
            *entry += tx.amount_cents;
        }

        tx.status = TxStatus::Committed;
        self.ledger.lock().unwrap().insert(tx_id.clone(), tx);

        Ok(tx_id)
    }

    fn graceful_shutdown(&self) {
        self.shutdown_flag.store(true, Ordering::SeqCst);
        // Allow in-flight transactions to complete
        thread::sleep(Duration::from_millis(100));

        let ledger = self.ledger.lock().unwrap();
        let pending: Vec<_> = ledger.values()
            .filter(|tx| tx.status == TxStatus::Pending || tx.status == TxStatus::Validated)
            .collect();

        if !pending.is_empty() {
            eprintln!("WARNING: {} transactions still in-flight during shutdown", pending.len());
        }
    }
}

fn main() {
    let engine = PaymentEngine::new(10_000_000_00); // $10M daily limit

    // Normal transaction
    match engine.process_payment("1,234.56", "USD", "merchant_001") {
        Ok(id) => println!("Processed: {}", id),
        Err(e) => println!("Failed: {}", e),
    }

    // European format
    match engine.process_payment("1.234,56", "EUR", "merchant_002") {
        Ok(id) => println!("Processed: {}", id),
        Err(e) => println!("Failed: {}", e),
    }

    engine.graceful_shutdown();
}
